using Dip.Application.Abstractions.Persistence; using Dip.Application.Abstractions.Time; using Dip.Domain.Entities; namespace Dip.Application.Features.Projects; public sealed record CreateProjectCommand(string Name,string RepositoryUrl,string DefaultBranch,DateTimeOffset? ReleaseDateUtc); public sealed record ProjectDto(Guid Id,string Name,string RepositoryUrl,string DefaultBranch,decimal HealthScore,DateTimeOffset? ReleaseDateUtc); public sealed class ProjectService{private readonly IProjectRepository _r;private readonly IUnitOfWork _u;private readonly ISystemClock _c;public ProjectService(IProjectRepository r,IUnitOfWork u,ISystemClock c){_r=r;_u=u;_c=c;} public async Task<ProjectDto>CreateAsync(CreateProjectCommand x,CancellationToken ct){var p=new Project(Guid.NewGuid(),x.Name,x.RepositoryUrl,x.DefaultBranch,_c.UtcNow);p.SetReleaseDate(x.ReleaseDateUtc);await _r.AddAsync(p,ct);await _u.SaveChangesAsync(ct);return Map(p);} public async Task<IReadOnlyList<ProjectDto>>ListAsync(CancellationToken ct)=>(await _r.ListAsync(ct)).Select(Map).ToArray(); public async Task<ProjectDto?>GetAsync(Guid id,CancellationToken ct){var p=await _r.GetByIdAsync(id,ct);return p is null?null:Map(p);} private static ProjectDto Map(Project p)=>new(p.Id,p.Name,p.RepositoryUrl,p.DefaultBranch,p.HealthScore.Value,p.ReleaseDateUtc);}